list_payment_gateways.code:
use WebCommander\Resources\PaymentGateways\PaymentGateways;

$response = PaymentGateways::listPaymentGateways($client, ['limit' => 20, 'offset' => 0, 'promotional' => 'false']);

foreach ($response->map['payment_gateways'] as $gateway) {
    echo $gateway['id'], ' ', $gateway['code'], ' ', $gateway['name'], $gateway['enabled'] ? ' (enabled)' : '', PHP_EOL;
}
echo $response->map['pagination']['has_next'] ? 'more pages' : 'last page', PHP_EOL;

update_payment_gateway.code:
use WebCommander\Resources\PaymentGateways\PaymentGateways;

$response = PaymentGateways::updatePaymentGateway($client, 2, [
    'information' => 'Make cheques payable to Example Store.',
]);

echo $response->map['payment_gateway']['information'], PHP_EOL;

patch_payment_gateway.code:
use WebCommander\Resources\PaymentGateways\PaymentGateways;

$response = PaymentGateways::patchPaymentGateway($client, 2, [
    'allowed_for' => ['store_pickup' => false],
]);

$allowedFor = $response->map['payment_gateway']['allowed_for'];
echo $allowedFor['store_pickup'] ? 'store pickup allowed' : 'store pickup not allowed', PHP_EOL;
